INSERT INTO `maestro_references` VALUES (1,'panji-sembahan','panji','Sembahan Awal','sembahan','maestro',NULL,NULL,NULL,NULL,NULL,0,0,NULL,0,0,NULL,NULL,NULL,'Gerakan penghormatan pembuka pada karakter Panji.','mudah',8,'[{\"icon\": \"⏱️\", \"text\": \"Tahan posisi sembahan selama 4-8 hitungan gamelan\", \"title\": \"Durasi\"}, {\"icon\": \"🎵\", \"text\": \"Mulai bersamaan dengan bunyi gong pembuka\", \"title\": \"Irama\"}, {\"icon\": \"👁️\", \"text\": \"Jaga konsentrasi dan kekhusyukan selama gerakan\", \"title\": \"Fokus\"}, {\"icon\": \"✨\", \"text\": \"Gerakan halus dan mengalir, tidak patah-patah\", \"title\": \"Kualitas\"}]','[{\"title\": \"Posisi Tubuh\", \"points\": [\"Duduk bersimpuh dengan kedua kaki terlipat rapi ke belakang\", \"Punggung tegak namun tidak kaku, bahu rileks\", \"Kepala sedikit menunduk sebagai tanda hormat\"]}, {\"title\": \"Posisi Tangan\", \"points\": [\"Kedua telapak tangan disatukan di depan dada\", \"Jari-jari mengarah ke atas, ibu jari menyentuh dada\", \"Siku rileks dan tidak terangkat tinggi\"]}, {\"title\": \"Ekspresi\", \"points\": [\"Mata setengah tertutup, pandangan ke bawah\", \"Wajah tenang dan khusyuk\", \"Napas perlahan dan teratur\"]}]',0,1,'2026-08-02 07:22:38','2026-08-02 07:22:38'),(2,'panji-nindak','panji','Nindak','nindak','maestro',NULL,NULL,NULL,NULL,NULL,0,0,NULL,0,0,NULL,NULL,NULL,'Langkah dasar yang lemah lembut pada karakter Panji.','mudah',4,'[{\"icon\": \"⏱️\", \"text\": \"4 hitungan gamelan\", \"title\": \"Durasi\"}, {\"icon\": \"🎭\", \"text\": \"Panji - Mudah\", \"title\": \"Karakter\"}, {\"icon\": \"🎵\", \"text\": \"60-80 BPM\", \"title\": \"Tempo\"}]','[{\"title\": \"Petunjuk Umum\", \"points\": [\"Perhatikan postur tubuh sesuai pakem karakter Panji\", \"Ikuti irama gamelan dengan tepat (4 hitungan)\", \"Jaga keseimbangan dan kontrol setiap transisi gerakan\"]}, {\"title\": \"Karakter Panji\", \"points\": [\"Karakter halus dan lembut, melambangkan kesucian jiwa manusia yang baru lahir.\", \"Ekspresi yang 