ro',NULL,NULL,NULL,NULL,NULL,0,0,NULL,0,0,NULL,NULL,NULL,'Kuda-kuda lebar & gagah pada karakter Klana.','menengah',4,'[{\"icon\": \"💪\", \"text\": \"Gunakan otot paha untuk menahan kuda-kuda rendah\", \"title\": \"Kekuatan\"}, {\"icon\": \"📐\", \"text\": \"Target sudut lutut sekitar 120-140 derajat\", \"title\": \"Sudut Lutut\"}, {\"icon\": \"🔥\", \"text\": \"Klana harus terlihat angkuh - jangan ragu membuka badan\", \"title\": \"Karakter\"}, {\"icon\": \"⚖️\", \"text\": \"Jaga berat badan merata, jangan condong ke satu sisi\", \"title\": \"Stabilitas\"}]','[{\"title\": \"Posisi Kaki\", \"points\": [\"Buka kaki lebih lebar dari bahu - Klana harus terlihat gagah dan menguasai panggung\", \"Tekuk kedua lutut membentuk kuda-kuda rendah yang kokoh\", \"Telapak kaki membuka ke luar sekitar 45 derajat\"]}, {\"title\": \"Posisi Badan\", \"points\": [\"Dada dibusungkan, bahu ditarik ke belakang dan dibuka lebar\", \"Berat badan merata, pusat gravitasi rendah dan stabil\", \"Punggung tetap tegak, jangan membungkuk\"]}, {\"title\": \"Posisi Tangan\", \"points\": [\"Kedua lengan diangkat setinggi bahu dengan siku ditekuk tegas\", \"Jari-jari mengembang penuh (ngruji), tidak lemas\", \"Pergelangan tangan aktif menekuk ke atas\"]}]',1,1,'2026-08-02 07:22:38','2026-08-02 07:22:38'),(25,'klana-ngabret_klana','klana','Ngabret','ngabret_klana','maestro',NULL,NULL,NULL,NULL,NULL,0,0,NULL,0,0,NULL,NULL,NULL,'Sentakan keras pada karakter Klana.','menengah',4,'[{\"icon\": \"⏱️\", \"text\": \"4 hitungan gamelan\", \"title\": \"Durasi\"}, {\"icon\": \"🎭\", \"text\": \"Klana - Sulit\", \"title\": \"Karakter\"}, {\"icon\": \"🎵\", \"text\": \"100-130 BPM\", \"title\": \"Tempo\"}]','[{\"title\": \"Petunjuk Umum\", \"points\": [\"Perhatikan postur tubuh sesuai pakem karakter Klana\", \"Ikuti irama gamelan dengan tepat (4 hitungan)\", \"Jaga keseimbangan dan kontrol setiap transisi gerakan\"]}, {\"title\": \"Karakter Klana\", \"points\": [\"Karakter dinamis dan angkara, melambangkan manusia yan